-- Private profile shared by future web/iOS clients. No UI activation or import.
alter table public.compte_profil
 add column objectif text not null default '' check(objectif in ('','career','interview','work','advanced','curious')),
 add column fuseau_horaire text not null default 'UTC',
 add column revision bigint not null default 1 check(revision>0);
revoke update(prenom) on public.compte_profil from authenticated;

-- Revisions and timestamps are generated by the server, including legacy writes.
create or replace function requete_private.compte_profil_dates()
returns trigger language plpgsql security invoker set search_path='' as $$
begin
 new.modifie_le:=clock_timestamp();new.revision:=old.revision+1;new.cree_le:=old.cree_le;
 return new;
end; $$;
alter policy compte_profil_lire on public.compte_profil using((select auth.uid())=user_id and coalesce((select auth.jwt()->>'is_anonymous'),'false')<>'true');
alter policy compte_profil_creer on public.compte_profil with check((select auth.uid())=user_id and coalesce((select auth.jwt()->>'is_anonymous'),'false')<>'true');
alter policy compte_profil_modifier on public.compte_profil using((select auth.uid())=user_id and coalesce((select auth.jwt()->>'is_anonymous'),'false')<>'true') with check((select auth.uid())=user_id and coalesce((select auth.jwt()->>'is_anonymous'),'false')<>'true');

create function requete_private.profil_uid()
returns uuid language plpgsql stable security invoker set search_path='' as $$
declare u uuid:=auth.uid();
begin
 if u is null or coalesce(auth.jwt()->>'is_anonymous','false')='true' or not exists(select 1 from auth.users where id=u) then raise exception 'Connexion requise' using errcode='42501'; end if;
 return u;
end; $$;
create function requete_private.profil_valide(p jsonb)
returns boolean language plpgsql stable security invoker set search_path='' as $$
begin
 if p is null or jsonb_typeof(p)<>'object' or p='{}'::jsonb or octet_length(p::text)>2048 or (p-'prenom'-'objectif'-'fuseau_horaire')<>'{}'::jsonb then return false;end if;
 if p?'prenom' and (jsonb_typeof(p->'prenom')<>'string' or char_length(p->>'prenom')>80 or p->>'prenom'<>btrim(p->>'prenom') or p->>'prenom' ~ '[[:cntrl:]]') then return false;end if;
 if p?'objectif' and (jsonb_typeof(p->'objectif')<>'string' or p->>'objectif' not in ('','career','interview','work','advanced','curious')) then return false;end if;
 if p?'fuseau_horaire' and (jsonb_typeof(p->'fuseau_horaire')<>'string' or length(p->>'fuseau_horaire')>100
  or (p->>'fuseau_horaire'<>'UTC' and position('/' in p->>'fuseau_horaire')=0)
  or not exists(select 1 from pg_catalog.pg_timezone_names where name=p->>'fuseau_horaire')) then return false;end if;
 return true;
end; $$;
create function public.compte_profil_lire()
returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=requete_private.profil_uid(); p jsonb;
begin
 select to_jsonb(c) into p from public.compte_profil c where user_id=u;
 return p;
end; $$;
create function public.compte_profil_creer(p_donnees jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=requete_private.profil_uid();
begin
 if not requete_private.profil_valide(p_donnees) then raise exception 'Profil invalide' using errcode='22023';end if;
 insert into public.compte_profil(user_id,prenom,objectif,fuseau_horaire)
 values(u,coalesce(p_donnees->>'prenom',''),coalesce(p_donnees->>'objectif',''),coalesce(p_donnees->>'fuseau_horaire','UTC')) on conflict(user_id) do nothing;
 return public.compte_profil_lire();
end; $$;
create function public.compte_profil_enregistrer(p_revision bigint,p_donnees jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=requete_private.profil_uid(); p jsonb;
begin
 if p_revision is null or p_revision<1 or not requete_private.profil_valide(p_donnees) then raise exception 'Profil invalide' using errcode='22023';end if;
 update public.compte_profil c set
  prenom=case when p_donnees?'prenom' then p_donnees->>'prenom' else c.prenom end,
  objectif=case when p_donnees?'objectif' then p_donnees->>'objectif' else c.objectif end,
  fuseau_horaire=case when p_donnees?'fuseau_horaire' then p_donnees->>'fuseau_horaire' else c.fuseau_horaire end
 where user_id=u and revision=p_revision returning to_jsonb(c) into p;
 if p is null then return jsonb_build_object('ok',false,'reason','revision_or_missing','profile',public.compte_profil_lire());end if;
 return jsonb_build_object('ok',true,'profile',p);
end; $$;
revoke all on function requete_private.profil_uid(),requete_private.profil_valide(jsonb) from public,anon,authenticated;
revoke all on function public.compte_profil_lire(),public.compte_profil_creer(jsonb),public.compte_profil_enregistrer(bigint,jsonb) from public,anon,authenticated;
grant execute on function public.compte_profil_lire(),public.compte_profil_creer(jsonb),public.compte_profil_enregistrer(bigint,jsonb) to authenticated;
